definition.script:
pipeline {
    agent any

    tools {
        nodejs 'NodeJS 22'
    }

    stages {
        stage('Checkout') {
            steps {
                // Checkout from the GitHub repository
                git url: 'https://github.com/eryon-ai/ATELIER_Clothing_Store.git', branch: 'main'
            }
        }

        stage('Install Dependencies') {
            steps {
                sh 'npm install'
            }
        }

        stage('Build') {
            steps {
                sh 'npm run build'
            }
        }

        stage('Simulate Deploy') {
            steps {
                echo 'Built dist/ successfully! In a real scenario, we would now push to AWS S3 or a web server.'
            }
        }
    }
}
